// Package clispec is the canonical definition of the shipped command line
// (issue #45). It is the single source of truth feeding both the --help
// output (main and cmd/support register their flags and usage text from
// here) and the Linux man pages generated by tools/buildman into man/man1/.
//
// Only shipped, user-facing commands belong here; internal development and
// CI scripts are deliberately not part of the command surface. Use invented
// examples only: no personal data or real file paths.
package clispec

// Program identity used by the generated pages.
const (
	Program = "coverage-audit"
	Version = "0.1.0"
	ManDate = "November 2026"
	Manual  = "Coverage Audit Manual"
)

// Kind is the value type of a flag.
type Kind int

const (
	String Kind = iota
	Int
	Bool
)

// Opt is one command-line flag. Go's flag package accepts -name and --name;
// the man pages document the single-dash form.
type Opt struct {
	Name  string
	Kind  Kind
	Def   string // default rendered in the docs
	Usage string
}

// Command is one shipped command: the auditor itself, or one support
// subcommand of the coverage-audit-support binary.
type Command struct {
	Name     string // page suffix; "" is the auditor itself
	Binary   string // executable name
	Summary  string
	Details  []string
	Options  []Opt
	Examples [][2]string // command line, explanation
}

// AuditOptions are the auditor's flags, in registration order.
var AuditOptions = []Opt{
	{"parcels", String, "data/ginot_hair_parcels.geojson", "local parcels GeoJSON"},
	{"published", String, "data/permit_requests.json", "published permit-requests feed"},
	{"checkpoint", String, "", "optional local checkpoint feed to validate against the next range"},
	{"batch-size", Int, "280", "planned next batch size"},
	{"plans", String, "", "optional public planning rows for observations"},
	{"as-of", String, "", "ISO observation date, explicit for reproducibility"},
	{"clean-out", String, "", "write a separate normalized dataset here; never overwrites the input"},
	{"previous", String, "", "optional previous public permit snapshot for comparison"},
	{"json", Bool, "false", "emit the report as JSON"},
	{"mcp", Bool, "false", "serve read-only MCP over stdio; data paths come from the flags, not from tool arguments"},
}

// Commands is the shipped command surface.
var Commands = []Command{
	{
		Name:    "",
		Binary:  Program,
		Summary: "audit published permit-request coverage against local parcels",
		Details: []string{
			"Reads local files only and compares the published permit-request feed against the local parcels dataset, reporting batch coverage and cursor consistency. Cursor progress is not verified query success. With -clean-out it writes a separate normalized dataset and never overwrites the input. With -mcp it serves read-only MCP over stdio.",
		},
		Options: AuditOptions,
		Examples: [][2]string{
			{"coverage-audit -json", "Print the coverage report as JSON."},
			{"coverage-audit -clean-out clean.json -as-of 2026-11-02", "Write a normalized dataset with an explicit observation date."},
		},
	},
	{
		Name:    "support",
		Binary:  Program + "-support",
		Summary: "CI support subcommands for the audit pipeline",
		Details: []string{
			"Support commands are separate from the offline auditor CLI and run in CI: fetch downloads the public source snapshot, callback reports run provenance, privacy scans the checkout for private data, bundle writes the result manifest, badges writes metric badge endpoints, and summary renders the run summary. Each takes exactly one subcommand name as its only argument.",
		},
		Examples: [][2]string{
			{"coverage-audit-support fetch", "Download the public source snapshot in CI."},
		},
	},
}

// SupportSubcommands are the valid subcommand names, in help order.
var SupportSubcommands = []string{"fetch", "callback", "privacy", "bundle", "badges", "summary"}
